<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Building2, CirclePlus, DoorOpen, House, Users, Wallet } from 'lucide-vue-next'
import { api, mediaUrl } from '../api'
import { useSessionStore } from '../stores/session'
const session=useSessionStore()
const properties=ref<any[]>([])
const units=ref<any[]>([])
const statement=ref<any>(null)
const loading=ref(true)
const saving=ref(false)
const error=ref('')
const form=ref({propertyId:'',unitNumber:'',bedrooms:'2',monthlyRent:''})
const occupied=computed(()=>units.value.filter((x)=>x.status==='OCCUPIED').length)
const canManageUnits=computed(()=>['ADMIN','OWNER'].includes(session.session?.user.role||''))
async function load(){loading.value=true;try{const [p,u,s]=await Promise.all([api.get('/portfolio/properties'),api.get('/units'),['ADMIN','OWNER'].includes(session.session?.user.role||'')?api.get('/workspace/statement'):Promise.resolve({data:null})]);properties.value=p.data;units.value=u.data;statement.value=s.data;if(!form.value.propertyId&&p.data.length)form.value.propertyId=p.data[0].id}catch(e:any){error.value=e.response?.data?.message||'Could not load your property portfolio.'}finally{loading.value=false}}
async function addUnit(){saving.value=true;error.value='';try{await api.post('/units',{...form.value,bedrooms:Number(form.value.bedrooms),monthlyRent:Number(form.value.monthlyRent)});form.value.unitNumber='';form.value.monthlyRent='';await load()}catch(e:any){error.value=e.response?.data?.message||'Could not add unit.'}finally{saving.value=false}}
const money=(n:any)=>`PKR ${Number(n).toLocaleString()}`
onMounted(load)
</script>

<template><section class="workspace-content"><div class="section-toolbar"><div><h2>Property portfolio</h2><p>See your listings, rental units, and occupied spaces in one place.</p></div><RouterLink to="/list-property" class="button button-outline"><CirclePlus :size="16"/> Add property</RouterLink></div><div v-if="error" class="notice error-notice">{{ error }}</div><div v-if="loading" class="loading-row">Loading your portfolio…</div><template v-else><div class="portfolio-summary"><article><span class="kpi-icon blue"><House/></span><small>Properties</small><b>{{properties.length}}</b></article><article><span class="kpi-icon green"><DoorOpen/></span><small>Total units</small><b>{{units.length}}</b></article><article><span class="kpi-icon purple"><Users/></span><small>Occupied</small><b>{{occupied}}</b></article><article><span class="kpi-icon gold"><Building2/></span><small>Vacant</small><b>{{units.length-occupied}}</b></article></div><div class="portfolio-layout"><div class="portfolio-list"><article v-for="p in properties" :key="p.id" class="portfolio-property"><img :src="mediaUrl(p.imageUrl)" :alt="p.title"/><div class="portfolio-property-main"><div class="property-status-line"><span class="status-pill" :class="p.status.toLowerCase()">{{p.status.replace('_',' ')}}</span><span>{{p.purpose==='RENT'?'For rent':'For sale'}} · {{p.type.toLowerCase()}}</span></div><h3>{{p.title}}</h3><p>{{p.community}}, {{p.city}}</p><div class="portfolio-property-foot"><b>{{p.purpose==='RENT'?money(p.price)+'/mo':money(p.price)}}</b><span>{{p.units.length}} units listed</span><RouterLink :to="`/property/${p.slug}`">View listing</RouterLink></div></div></article><div v-if="!properties.length" class="empty-state compact-empty"><h3>No properties in your portfolio</h3><p>Add a property and manage its units here.</p><RouterLink class="button button-primary" to="/list-property">Add your first property</RouterLink></div></div><form v-if="canManageUnits" class="panel-card compact-form" @submit.prevent="addUnit"><div class="eyebrow muted-eyebrow">UNIT INVENTORY</div><h3>Add a rentable unit</h3><p>Units connect to your building and can be selected when an application becomes a lease.</p><label>Property<select v-model="form.propertyId" required><option v-for="p in properties" :key="p.id" :value="p.id">{{p.title}}</option></select></label><label>Unit number<input v-model="form.unitNumber" required placeholder="e.g. 4B"/></label><label>Bedrooms<input v-model="form.bedrooms" type="number" min="0" required/></label><label>Monthly rent (PKR)<input v-model="form.monthlyRent" type="number" min="1" required placeholder="185000"/></label><button class="button button-primary full-button" :disabled="saving||!properties.length">{{saving?'Saving…':'Add unit'}}</button></form></div><section v-if="units.length" class="unit-table-wrap"><div class="section-toolbar"><div><h2>Units</h2><p>Availability updates when you create a lease.</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>UNIT</th><th>PROPERTY</th><th>BEDROOMS</th><th>MONTHLY RENT</th><th>STATUS</th></tr></thead><tbody><tr v-for="unit in units" :key="unit.id"><td><b>{{unit.unitNumber}}</b></td><td>{{unit.property.title}}</td><td>{{unit.bedrooms}}</td><td>{{money(unit.monthlyRent)}}</td><td><span class="status-pill" :class="unit.status.toLowerCase()">{{unit.status}}</span></td></tr></tbody></table></div></section><section v-if="statement" class="statement-card"><div class="section-toolbar"><div><h2>Owner statement snapshot</h2><p>Recorded rent less maintenance quotes so far.</p></div><span class="kpi-icon green"><Wallet/></span></div><div class="statement-totals"><div><small>Rent collected</small><b>{{money(statement.totals.rentCollected)}}</b></div><div><small>Maintenance costs</small><b>{{money(statement.totals.maintenanceCost)}}</b></div><div><small>Net income</small><b>{{money(statement.totals.netIncome)}}</b></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>PROPERTY</th><th>RENT COLLECTED</th><th>MAINTENANCE</th><th>NET</th></tr></thead><tbody><tr v-for="row in statement.rows" :key="row.propertyId"><td>{{row.property}}</td><td>{{money(row.rentCollected)}}</td><td>{{money(row.maintenanceCost)}}</td><td><b>{{money(row.netIncome)}}</b></td></tr></tbody></table></div></section></template></section></template>
